1	/* ============================ Lái xe máy: hình xe (phần hình tạm) ============================
2	   BkBike: một nhóm đặt ở điểm giữa hai vệt bánh trên mặt đường (tâm thân xe, y = mặt đường), xoay yaw quanh Y rồi pitch quanh Z cục bộ (như DrCar);
3	   bên trong một nút cuộn `lean` quanh trục dọc X cục bộ đi qua mặt đường (đường chạm đất): lean > 0 nghiêng trái (−Z cục bộ khi mũi +X), nên
4	   cuộn là −lean quanh +X. Tấm bóng mờ ở nhóm ngoài (không cuộn theo xe).
5	   - Hình tạm: hình 'bike' của common/vehicles/shapes.ts (xe tay ga + người lái đội mũ, mũi +X, mặt đường y = 0) chép ra, tô màu các phần
6	     màu theo instance (sơn, áo, mũ) bằng CONFIG.bike.model.temp, giãn theo X cho đúng chiều dài thân va chạm (CONFIG.bike.body.length). Một Mesh.
7	   - Lớp 1 (không vào phản chiếu mặt nước), không đổ / nhận bóng; vật liệu cùng tham số với hình tạm / tấm bóng của ô tô (drive/car.ts) nên
8	     dùng chung program đã có, không biên dịch thêm.
9	   - Mô hình thật (public/bike/scooter.glb, bánh, cổ lái, giảm xóc, đèn): Task 3. place() đã nhận đủ trường cho phần đó.
10	   Không cấp phát mỗi khung (D-018). */
11	import * as THREE from 'three';
12	import { CONFIG } from '../../config';
13	import { vhBuildTypeGeometry, Role } from '../../common/vehicles/shapes';
14	
15	export interface BkPlace { x: number; y: number; z: number; yaw: number; pitch: number; lean: number; steer: number; wheel: number; susF: number; susR: number; braking: boolean; sig: -1 | 0 | 1 }
16	
17	const B = CONFIG.bike.body, M = CONFIG.bike.model;
18	const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
19	const _q = new THREE.Quaternion();
20	
21	/* ===== Vật liệu, hình học dùng chung ===== */
22	let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null;
23	
24	/* Hình tạm: chép hình 'bike' của đội xe, bỏ aRole, tô màu phần màu theo instance, giãn X về chiều dài thân */
25	function bkTempGeometry(): THREE.BufferGeometry {
26	  const g = vhBuildTypeGeometry('bike').clone();
27	  const role = g.getAttribute('aRole') as THREE.BufferAttribute, col = g.getAttribute('color') as THREE.BufferAttribute;
28	  const T = M.temp, paint = new THREE.Color(T.paint), shirt = new THREE.Color(T.shirt), helmet = new THREE.Color(T.helmet);
29	  for (let i = 0; i < role.count; i++) {
30	    const r = role.getX(i), c = r === Role.Paint ? paint : r === Role.Accent ? shirt : r === Role.Helmet ? helmet : null;
31	    if (c) col.setXYZ(i, c.r, c.g, c.b);
32	  }
33	  g.deleteAttribute('aRole');
34	  g.computeBoundingBox();
35	  const bb = g.boundingBox!, len = bb.max.x - bb.min.x;
36	  g.scale(B.length / len, 1, 1);                                     // mặt cắt giữ nguyên, chỉ dài theo thân va chạm
37	  g.computeBoundingBox(); g.computeBoundingSphere();
38	  return g;
39	}
40	
41	/* Tấm bóng mờ: như drShadowShared của ô tô (mép mềm hình vuông bo), cùng tham số vật liệu ⇒ cùng program */
42	function bkShadowShared(): void {
43	  if (shadowMat) return;
44	  const n = 32, d = new Uint8Array(n * n * 4);
45	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
46	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
47	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;
48	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
49	  }
50	  const tex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); tex.needsUpdate = true;
51	  tex.magFilter = tex.minFilter = THREE.LinearFilter;
52	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: tex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
53	  shadowMat.name = 'bikeShadow';
54	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
55	}
56	function bkTempMaterial(): THREE.MeshStandardMaterial {
57	  if (!tempMat) { tempMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.1 }); tempMat.name = 'bikeTemp'; }
58	  return tempMat;
59	}
60	
61	/* ===== Một xe máy ===== */
62	export class BkBike {
63	  readonly group = new THREE.Group();
64	  private readonly roll = new THREE.Group();                         // nút cuộn lean quanh đường chạm đất
65	  private temp: THREE.Mesh | null;
66	  private tempGeo: THREE.BufferGeometry | null;
67	  private disposed = false;
68	
69	  constructor() {
70	    this.group.name = 'bike';
71	    this.group.add(this.roll);
72	    this.tempGeo = bkTempGeometry();
73	    this.temp = new THREE.Mesh(this.tempGeo, bkTempMaterial());
74	    this.temp.name = 'bike-temp';
75	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
76	    this.roll.add(this.temp);
77	    bkShadowShared();
78	    const sh = new THREE.Mesh(shadowGeo!, shadowMat!);
79	    sh.scale.set(B.length + 2 * M.shadow.pad, 1, B.width + 2 * M.shadow.pad);
80	    sh.position.y = M.shadow.lift;
81	    sh.layers.set(1); sh.castShadow = false; sh.receiveShadow = false; sh.renderOrder = 1;
82	    this.group.add(sh);
83	  }
84	
85	  /* Có mô hình thật chưa (Task 3); hình tạm thì false */
86	  get real(): boolean { return false; }
87	
88	  place(p: BkPlace): void {
89	    const g = this.group;
90	    g.position.set(p.x, p.y, p.z);
91	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(_q.setFromAxisAngle(AXZ, p.pitch));
92	    this.roll.rotation.x = -p.lean;                                  // lean > 0 nghiêng trái (−Z cục bộ)
93	  }
94	
95	  dispose(): void {
96	    if (this.disposed) return;
97	    this.disposed = true;
98	    this.group.removeFromParent();
99	    if (this.temp) { this.roll.remove(this.temp); this.temp = null; }
100	    this.tempGeo?.dispose(); this.tempGeo = null;
101	  }
102	}
