1	/* ===== Lái xe: hình chiếc VinFast VF 3 trong cảnh (D-034) =====
2	   - drCarLoad(): import() động GLTFLoader, nạp public/car/vf3.glb một lần, nhớ đệm. Lỗi bất kỳ hoặc quá model.timeoutMs → console.warn, null; promise không bao giờ bị từ chối. Quá giờ mà sau đó nạp xong thì xe đang có vẫn đổi sang mô hình thật.
3	     Nguồn được chuẩn hóa một lần: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng; hai vật liệu đèn vá bằng onBeforeCompile (đọc shared.uNight, không PointLight);
4	     chờ drCarSetWarm (compileAsync theo cảnh chính, ≤ model.warmMs; phủ cảnh nguồn, bánh instanced, hình tạm, tấm bóng) rồi mới trả nguồn.
5	   - Đèn: lamp_head có emissive map của nguồn, nhân hệ số theo uNight. lamp_tail không có: phát sáng = màu cơ bản (cả logo trong ảnh dán) × model.tailTint (đỏ) × hệ số. Kính (Material.002) đặt nhám model.glassRough.
6	     Đèn phanh = bản vật liệu thứ hai cùng program (cùng customProgramCacheKey, chỉ khác uniform uBrake): đổi tham chiếu vật liệu của lưới đèn hậu, không biên dịch lại.
7	   - DrCar: group có ngay với hình tạm (một Mesh gộp hộp bo + bốn trụ bánh, màu theo slot) và tấm bóng mờ dưới gầm; nạp xong thì đổi sang bản sao `body` của mô hình
8	     (5 primitive = 5 lệnh vẽ, vật liệu `paint` nhân bản riêng để đặt màu slot). Bốn bánh KHÔNG thuộc group của xe: nằm trong drWheels, mỗi vật liệu của lưới bánh một
9	     InstancedMesh dùng chung cho mọi xe (3 lệnh vẽ tổng cộng), mỗi xe giữ 4 chỗ liên tiếp. drWheels.group phải nằm trong cảnh (drCars.group chứa sẵn).
10	     Lệnh vẽ: hình tạm 2 / xe; mô hình thật 5 thân + 1 bóng = 6 / xe, cộng 3 lệnh bánh chung.
11	   - Quy ước hướng: yaw 0 = mũi +X; steer > 0 rẽ trái (cùng chiều yaw); wheel = góc lăn bánh trái (rad, tăng khi xe tiến). Mô hình: mũi +X, Y lên, đáy lốp y = 0, gốc giữa hai trục.
12	     Bánh phải dùng chung lưới với bánh trái nên nút xoay 180 độ quanh Y: dấu quay quanh Z cục bộ lấy theo hướng Z cục bộ của bánh trong thế giới.
13	   Không cấp phát mỗi khung. docs/superpowers/specs/2026-11-12-lai-xe-oto-design.md */
14	import * as THREE from 'three';
15	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
16	import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
17	import { CONFIG } from '../../config';
18	import { shared } from '../../core/shared';
19	import { multiParams } from '../multi/params';
20	
21	const M = CONFIG.drive.model, CAR = CONFIG.drive.car;
22	const WHEELS = ['wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr'];   // hai bánh đầu là bánh trước
23	const CAP = (multiParams.slots + 1) * 4;                           // chỗ bánh: 6 xe × 4
24	
25	export interface DrPlace { x: number; y: number; z: number; yaw: number; pitch: number; steer: number; wheel: number; braking: boolean }
26	
27	/* ===== Vật liệu đèn: vá phát sáng theo uNight, hệ số `night`; uBrake > phát sáng nền thì thay bằng uBrake ===== */
28	function drLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, brake: number): void {
29	  const ub = { value: brake };
30	  m.onBeforeCompile = (s) => {
31	    s.uniforms.uNight = shared.uNight;
32	    s.uniforms.uBrake = ub;
33	    s.fragmentShader = 'uniform float uNight;\nuniform float uBrake;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
34	      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uBrake );`);
35	  };
36	  m.customProgramCacheKey = () => key;
37	  m.userData.lampBrake = brake;
38	}
39	
40	export interface DrSource {
41	  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
42	  body: THREE.Object3D;                        // nút body
43	  paint: THREE.MeshStandardMaterial;           // vật liệu sơn gốc (mỗi xe nhân bản)
44	  tail: THREE.Material; tailBrake: THREE.Material;
45	  wheels: { pos: THREE.Vector3; quat: THREE.Quaternion; sign: number }[];   // vị trí, xoay nghỉ, dấu quay quanh Z cục bộ (4 bánh theo WHEELS)
46	  wheelMeshes: THREE.Mesh[];                   // các lưới của wheel_fl (mỗi vật liệu một lưới)
47	}
48	
49	/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu thì ném lỗi (drCarLoad bắt, trả null) */
50	export function drCarSource(scene: THREE.Object3D): DrSource {
51	  scene.updateMatrixWorld(true);
52	  const body = scene.getObjectByName('body');
53	  if (!body) throw new Error('thiếu nút body');
54	  let paint: THREE.MeshStandardMaterial | null = null, head: THREE.MeshStandardMaterial | null = null, tail: THREE.MeshStandardMaterial | null = null;
55	  scene.traverse((o) => {
56	    o.layers.set(1);
57	    const me = o as THREE.Mesh;
58	    if (!me.isMesh) return;
59	    me.castShadow = false; me.receiveShadow = false;
60	    const mat = me.material as THREE.MeshStandardMaterial;
61	    if (mat.name === 'paint') paint = mat;
62	    else if (mat.name === 'lamp_head') head = mat;
63	    else if (mat.name === 'lamp_tail') tail = mat;
64	    else if (mat.name === 'Material.002') mat.roughness = M.glassRough;   // kính: nguồn nhám 0 ⇒ điểm chói trăng loang xanh (cả bản sao thân dùng chung vật liệu này)
65	  });
66	  if (!paint || !head || !tail) throw new Error('thiếu vật liệu paint / lamp_head / lamp_tail');
67	  const h = head as THREE.MeshStandardMaterial, t = tail as THREE.MeshStandardMaterial;
68	  drLampPatch(h, 'drLampHead', M.headNight, 0);
69	  t.emissive.set(M.tailTint); t.emissiveMap = t.map; t.emissiveIntensity = 1;   // không emissive map: lấy chính ảnh màu cơ bản, nhuộm đỏ (ảnh dán nhạt × trắng = hồng)
70	  drLampPatch(t, 'drLampTail', M.tailNight, 0);
71	  const tb = t.clone(); drLampPatch(tb, 'drLampTail', M.tailNight, M.tailBrake);   // cùng khóa program: chỉ khác uniform
72	  const wheels: DrSource['wheels'] = [], z = new THREE.Vector3();
73	  for (const n of WHEELS) {
74	    const w = scene.getObjectByName(n);
75	    if (!w) throw new Error(`thiếu nút ${n}`);
76	    z.set(0, 0, 1).applyQuaternion(w.quaternion);
77	    wheels.push({ pos: w.position.clone(), quat: w.quaternion.clone(), sign: z.z > 0 ? -1 : 1 });   // bánh tiến: quanh +Z thế giới góc âm
78	  }
79	  const wheelMeshes: THREE.Mesh[] = [];
80	  scene.getObjectByName(WHEELS[0]).traverse((o) => { if ((o as THREE.Mesh).isMesh) wheelMeshes.push(o as THREE.Mesh); });
81	  if (!wheelMeshes.length) throw new Error('bánh không có lưới');
82	  return { scene, body, paint: paint as THREE.MeshStandardMaterial, tail: t, tailBrake: tb, wheels, wheelMeshes };
83	}
84	
85	/* ===== Nạp (nhớ đệm) ===== */
86	let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
87	export function drCarSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
88	async function drCarWarm(o: THREE.Object3D): Promise<void> {
89	  if (!warm) return;
90	  let timer = 0;
91	  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
92	  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
93	  finally { clearTimeout(timer); }
94	}
95	
96	/* Làm nóng mọi thứ xe dùng, không chỉ cảnh nguồn: bánh vẽ bằng InstancedMesh (program USE_INSTANCING khác program của lưới thường),
97	   hình tạm (driveTemp) và tấm bóng (driveShadow). Nhóm tạm gồm cảnh nguồn + một InstancedMesh 1 chỗ mỗi lưới bánh + một hình tạm + một tấm bóng;
98	   gỡ cảnh nguồn ra (về không cha) và bỏ nhóm sau khi làm nóng. Đèn hậu phanh cùng program với đèn hậu (cùng khóa) nên không cần */
99	async function drCarWarmAll(src: DrSource): Promise<void> {
100	  if (!warm) return;
101	  const g = new THREE.Group(), ims: THREE.InstancedMesh[] = [];
102	  for (const m of src.wheelMeshes) { const im = new THREE.InstancedMesh(m.geometry, m.material, 1); im.layers.set(1); ims.push(im); g.add(im); }
103	  const tg = drTempGeometry('#808080');
104	  g.add(new THREE.Mesh(tg, drTempMaterial()));
105	  drShadowShared(); g.add(new THREE.Mesh(shadowGeo!, shadowMat!));
106	  g.add(src.scene);
107	  try { await drCarWarm(g); }
108	  finally { g.remove(src.scene); for (const im of ims) im.dispose(); tg.dispose(); }
109	}
110	
111	async function drCarDefaultLoader(): Promise<THREE.Object3D> {
112	  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
113	  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
114	  return gltf.scene;
115	}
116	
117	let loader: () => Promise<THREE.Object3D> = drCarDefaultLoader;
118	let cache: Promise<THREE.Object3D | null> | null = null;
119	let late: Promise<THREE.Object3D | null> | null = null;   // nạp không giới hạn giờ: DrCar đổi sang mô hình thật cả khi xong sau timeoutMs
120	let sources = new WeakMap<THREE.Object3D, DrSource>();
121	
122	/* Nạp mô hình xe. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null.
123	   Quá giờ chỉ là câu trả lời của drCarLoad: việc nạp vẫn chạy tiếp, xe đang có (DrCar) đổi sang mô hình thật khi nó xong (late) */
124	export function drCarLoad(): Promise<THREE.Object3D | null> {
125	  if (cache) return cache;
126	  const work = (async () => {
127	    const scene = await loader();
128	    const src = drCarSource(scene);
129	    sources.set(scene, src);
130	    await drCarWarmAll(src);
131	    return scene as THREE.Object3D | null;
132	  })();
133	  let timer = 0;
134	  const p = Promise.race([work, new Promise<null>((r) => { timer = setTimeout(() => r(null), M.timeoutMs) as unknown as number; })])
135	    .catch((e) => { console.warn('Lái xe: không nạp được mô hình xe, dùng hình tạm', e); return null; })
136	    .finally(() => clearTimeout(timer));
137	  late = work.catch(() => null);   // lỗi đã báo ở nhánh race
138	  cache = p;
139	  return p;
140	}
141	
142	/* Cho test: thay bộ nạp (null: mặc định), xóa đệm, bỏ bánh dùng chung */
143	export function drCarSetLoader(fn: (() => Promise<THREE.Object3D>) | null): void {
144	  loader = fn || drCarDefaultLoader; cache = null; late = null; sources = new WeakMap();
145	  drWheels.reset();
146	}
147	
148	/* ===== Bánh dùng chung: mỗi vật liệu một InstancedMesh, CAP chỗ ===== */
149	const A = new THREE.Matrix4(), B = new THREE.Matrix4(), Q = new THREE.Quaternion(), Q2 = new THREE.Quaternion(), UNIT = new THREE.Vector3(1, 1, 1), ZERO = new THREE.Matrix4().makeScale(0, 0, 0);
150	const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
151	
152	class DrWheelPool {
153	  readonly group = new THREE.Group();
154	  meshes: THREE.InstancedMesh[] = [];
155	  private src: DrSource | null = null;
156	  private used: boolean[] = new Array(CAP / 4).fill(false);
157	  constructor() { this.group.name = 'drive-wheels'; this.group.visible = false; }
158	  /* Dựng 3 InstancedMesh từ lưới bánh của nguồn (một lần cho mỗi nguồn) */
159	  setup(src: DrSource): void {
160	    if (this.src === src) return;
161	    this.reset();
162	    this.src = src;
163	    for (const m of src.wheelMeshes) {
164	      const im = new THREE.InstancedMesh(m.geometry, m.material, CAP);
165	      im.name = 'drive-wheels-' + (Array.isArray(m.material) ? '' : m.material.name);
166	      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
167	      for (let i = 0; i < CAP; i++) im.setMatrixAt(i, ZERO);
168	      im.count = 0; im.frustumCulled = false; im.castShadow = false; im.receiveShadow = false; im.layers.set(1);
169	      this.meshes.push(im); this.group.add(im);
170	    }
171	  }
172	  /* Chỗ trống đầu tiên (chỉ số instance đầu của 4 bánh), -1 nếu hết */
173	  acquire(): number {
174	    const k = this.used.indexOf(false);
175	    if (k < 0) return -1;
176	    this.used[k] = true;
177	    this.group.visible = true;
178	    this.fit();
179	    return k * 4;
180	  }
181	  release(base: number): void {
182	    if (base < 0) return;
183	    this.used[base / 4] = false;
184	    for (const im of this.meshes) { for (let i = 0; i < 4; i++) im.setMatrixAt(base + i, ZERO); im.instanceMatrix.needsUpdate = true; }
185	    this.fit();
186	  }
187	  private fit(): void {
188	    const top = this.used.lastIndexOf(true);
189	    for (const im of this.meshes) im.count = (top + 1) * 4;
190	    this.group.visible = top >= 0;
191	  }
192	  /* Ma trận 4 bánh của xe có ma trận thế giới `car` */
193	  set(base: number, car: THREE.Matrix4, steer: number, wheel: number): void {
194	    const w = this.src!.wheels;
195	    for (let i = 0; i < 4; i++) {
196	      const d = w[i];
197	      Q.setFromAxisAngle(AXY, i < 2 ? steer : 0).multiply(d.quat).multiply(Q2.setFromAxisAngle(AXZ, d.sign * wheel));   // lái (chỉ bánh trước), xoay nghỉ của nút, rồi lăn quanh Z cục bộ
198	      A.compose(d.pos, Q, UNIT);
199	      B.multiplyMatrices(car, A);
200	      for (const im of this.meshes) im.setMatrixAt(base + i, B);
201	    }
202	    for (const im of this.meshes) im.instanceMatrix.needsUpdate = true;
203	  }
204	  reset(): void {
205	    for (const im of this.meshes) { this.group.remove(im); im.dispose(); }
206	    this.meshes = []; this.src = null; this.used.fill(false); this.group.visible = false;
207	  }
208	}
209	const B3 = new THREE.Quaternion();
210	export const drWheels = new DrWheelPool();
211	
212	/* ===== Hình tạm và tấm bóng dùng chung ===== */
213	let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null, shadowTex: THREE.DataTexture | null = null;
214	
215	function drTempGeometry(color: string): THREE.BufferGeometry {
216	  const L = CAR.length, W = CAR.width, H = CAR.height - CAR.clearance, r = CAR.wheelDia / 2, ww = M.temp.wheelWidth;
217	  const col = new THREE.Color(color), dark = new THREE.Color(0x15151a);
218	  const paint = (g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry => {
219	    const n = g.attributes.position.count, a = new Float32Array(n * 3);
220	    for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
221	    g.setAttribute('color', new THREE.BufferAttribute(a, 3));
222	    return g;
223	  };
224	  const parts: THREE.BufferGeometry[] = [paint(new RoundedBoxGeometry(L, H, W, 2, 0.12).translate(0, CAR.clearance + H / 2, 0), col)];
225	  const ax = CAR.wheelbase / 2, az = W / 2 - ww / 2;
226	  for (const sx of [1, -1]) for (const sz of [1, -1]) {
227	    parts.push(paint(new THREE.CylinderGeometry(r, r, ww, 12).rotateX(Math.PI / 2).translate(sx * ax, r, sz * az), dark));
228	  }
229	  const g = mergeGeometries(parts.map((p) => p.index ? p.toNonIndexed() : p))!;   // 1 Mesh gộp
230	  for (const p of parts) p.dispose();
231	  return g;
232	}
233	
234	function drShadowShared(): void {
235	  if (shadowMat) return;
236	  const n = 32, d = new Uint8Array(n * n * 4);
237	  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
238	    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
239	    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;   // mép mềm hình vuông bo
240	    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
241	  }
242	  shadowTex = new THREE.DataTexture(d, n, n, THREE.RGBAFormat); shadowTex.needsUpdate = true;
243	  shadowTex.magFilter = shadowTex.minFilter = THREE.LinearFilter;
244	  shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, map: shadowTex, transparent: true, opacity: M.shadow.opacity, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false });
245	  shadowMat.name = 'driveShadow';
246	  shadowGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2);
247	}
248	function drTempMaterial(): THREE.MeshStandardMaterial {
249	  if (!tempMat) { tempMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.6, metalness: 0.1 }); tempMat.name = 'driveTemp'; }
250	  return tempMat;
251	}
252	/* Giải phóng vật liệu / bánh dùng chung (rời chế độ hẳn) */
253	export function drCarDisposeShared(): void {
254	  drWheels.reset();
255	  tempMat?.dispose(); tempMat = null;
256	  shadowMat?.dispose(); shadowGeo?.dispose(); shadowTex?.dispose(); shadowMat = null; shadowGeo = null; shadowTex = null;
257	}
258	
259	/* ===== Một xe ===== */
260	export class DrCar {
261	  readonly group = new THREE.Group();
262	  private readonly color: string;
263	  private temp: THREE.Mesh | null;
264	  private tempGeo: THREE.BufferGeometry | null;
265	  private shadow: THREE.Mesh;
266	  private body: THREE.Object3D | null = null;
267	  private paint: THREE.MeshStandardMaterial | null = null;
268	  private tailMeshes: THREE.Mesh[] = [];
269	  private src: DrSource | null = null;
270	  private slot = -1;
271	  private disposed = false;
272	  private brakingNow = false;
273	  private last: DrPlace | null = null;
274	
275	  constructor(color: string) {
276	    this.color = color;
277	    this.group.name = 'drive-car';
278	    this.group.matrixAutoUpdate = true;
279	    this.tempGeo = drTempGeometry(color);
280	    this.temp = new THREE.Mesh(this.tempGeo, drTempMaterial());
281	    this.temp.layers.set(1); this.temp.castShadow = false; this.temp.receiveShadow = false;
282	    this.group.add(this.temp);
283	    drShadowShared();
284	    this.shadow = new THREE.Mesh(shadowGeo!, shadowMat!);
285	    this.shadow.scale.set(CAR.length + 2 * M.shadow.pad, 1, CAR.width + 2 * M.shadow.pad);
286	    this.shadow.position.y = M.shadow.lift;
287	    this.shadow.layers.set(1); this.shadow.castShadow = false; this.shadow.receiveShadow = false; this.shadow.renderOrder = 1;
288	    this.group.add(this.shadow);
289	    void drCarLoad();
290	    late!.then((scene) => { const src = scene && sources.get(scene); if (src && !this.disposed) this.swap(src); });   // không bao giờ từ chối; nguồn của bộ nạp cũ (test đổi bộ nạp) thì bỏ
291	  }
292	
293	  get real(): boolean { return this.body !== null; }
294	
295	  /* Đổi hình tạm sang bản sao mô hình thật, giữ nguyên vị trí */
296	  private swap(src: DrSource): void {
297	    if (this.body) return;
298	    drWheels.setup(src);
299	    this.slot = drWheels.acquire();
300	    this.src = src;
301	    const body = src.body.clone();
302	    this.paint = src.paint.clone();
303	    this.paint.color.set(this.color); this.paint.roughness = M.paintRough; this.paint.metalness = M.paintMetal;
304	    body.traverse((o) => {
305	      const m = o as THREE.Mesh;
306	      if (!m.isMesh) return;
307	      const mat = m.material as THREE.Material;
308	      if (mat.name === 'paint') m.material = this.paint!;
309	      else if (mat === src.tail) this.tailMeshes.push(m);
310	    });
311	    this.body = body;
312	    this.group.add(body);
313	    if (this.temp) { this.group.remove(this.temp); this.temp = null; this.tempGeo!.dispose(); this.tempGeo = null; }
314	    this.brakingNow = false;
315	    if (this.last) this.place(this.last);
316	  }
317	
318	  place(p: DrPlace): void {
319	    const l = this.last || (this.last = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, steer: 0, wheel: 0, braking: false });
320	    l.x = p.x; l.y = p.y; l.z = p.z; l.yaw = p.yaw; l.pitch = p.pitch; l.steer = p.steer; l.wheel = p.wheel; l.braking = p.braking;
321	    const g = this.group;
322	    g.position.set(p.x, p.y, p.z);
323	    g.quaternion.setFromAxisAngle(AXY, p.yaw).multiply(B3.setFromAxisAngle(AXZ, p.pitch));
324	    if (!this.body) return;
325	    if (p.braking !== this.brakingNow) {
326	      this.brakingNow = p.braking;
327	      const mat = p.braking ? this.src!.tailBrake : this.src!.tail;
328	      for (const m of this.tailMeshes) m.material = mat;
329	    }
330	    if (this.slot >= 0) { g.updateMatrix(); drWheels.set(this.slot, g.matrix, p.steer, p.wheel); }
331	  }
332	
333	  dispose(): void {
334	    if (this.disposed) return;
335	    this.disposed = true;
336	    this.group.removeFromParent();
337	    drWheels.release(this.slot); this.slot = -1;
338	    this.tempGeo?.dispose(); this.tempGeo = null;
339	    this.paint?.dispose(); this.paint = null;
340	    this.body = null; this.temp = null; this.tailMeshes.length = 0;
341	  }
342	}
343	
344

