1	/* ============================ Lái xe máy: hình xe (phần hình tạm) ============================
2	   BkBike: một nhóm đặt ở điểm giữa hai vệt bánh trên mặt đường (tâm thân xe, y = mặt đường), xoay yaw quanh Y rồi pitch quanh Z cục bộ (như DrCar);
3	   bên trong một nút cuộn `lean` quanh trục dọc X cục bộ đi qua mặt đường (đường chạm đất): lean > 0 nghiêng trái (−Z cục bộ khi mũi +X), nên
4	   cuộn là −lean quanh +X. Tấm bóng mờ ở nhóm ngoài (không cuộn theo xe).
5	   - Hình tạm: hình 'bike' của common/vehicles/shapes.ts (xe tay ga + người lái đội mũ, mũi +X, mặt đường y = 0) chép ra, tô màu các phần
6	     màu theo instance (sơn, áo, mũ) bằng CONFIG.bike.model.temp, giãn theo X cho đúng chiều dài thân va chạm (CONFIG.bike.body.length). Một Mesh.
7	   - Lớp 1 (không vào phản chiếu mặt nước), không đổ / nhận bóng; vật liệu cùng tham số với hình tạm / tấm bóng của ô tô (drive/car.ts) nên
8	     dùng chung program đã có, không biên dịch thêm.
9	   - Mô hình thật (public/bike/scooter.glb, bánh, cổ lái, giảm xóc, đèn): Task 3. place() đã nhận đủ trường cho phần đó.
10	   Không cấp phát mỗi khung (D-018). */
11	import * as THREE from 'three';
12	import { CONFIG } from '../../config';
13	import { vhBuildTypeGeometry, Role } from '../../common/vehicles/shapes';
14	
15	export interface BkPlace { x: number; y: number; z: number; yaw: number; pitch: number; lean: number; steer: number; wheel: number; susF: number; susR: number; braking: boolean; sig: -1 | 0 | 1 }
16	
17	const B = CONFIG.bike.body, M = CONFIG.bike.model;
18	const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
19	const _q = new THREE.Quaternion();
20	
21	/* ===== Vật liệu, hình học dùng chung ===== */
22	let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null;
23	
24	/* Hình tạm: chép hình 'bike' của đội xe, bỏ aRole, tô màu phần màu theo instance, giãn X về chiều dài thân */
25	function bkTempGeometry(): THREE.BufferGeometry {
26	  const g = vhBuildTypeGeometry('bike').clone();
27	  const role = g.getAttribute('aRole') as THREE.BufferAttribute, col = g.getAttribute('color') as THREE.BufferAttribute;
