215	function drTempGeometry(color: string): THREE.BufferGeometry {
216	  const L = CAR.length, W = CAR.width, H = CAR.height - CAR.clearance, r = CAR.wheelDia / 2, ww = M.temp.wheelWidth;
217	  const col = new THREE.Color(color), dark = new THREE.Color(0x15151a);
218	  const paint = (g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry => {
219	    const n = g.attributes.position.count, a = new Float32Array(n * 3);
220	    for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
221	    g.setAttribute('color', new THREE.BufferAttribute(a, 3));
222	    return g;
223	  };
224	  const parts: THREE.BufferGeometry[] = [paint(new RoundedBoxGeometry(L, H, W, 2, 0.12).translate(0, CAR.clearance + H / 2, 0), col)];
225	  const ax = CAR.wheelbase / 2, az = W / 2 - ww / 2;
226	  for (const sx of [1, -1]) for (const sz of [1, -1]) {
227	    parts.push(paint(new THREE.CylinderGeometry(r, r, ww, 12).rotateX(Math.PI / 2).translate(sx * ax, r, sz * az), dark));
228	  }
229	  const g = mergeGeometries(parts.map((p) => p.index ? p.toNonIndexed() : p))!;   // 1 Mesh gộp
230	  for (const p of parts) p.dispose();
231	  return g;
232	}
