74	  const j = glbJson(FILE);
75	  for (const n of ['vf3', 'body', 'wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr']) nodeByName(j, n);
76	  const c = Object.fromEntries(['fl', 'fr', 'rl', 'rr'].map(k => [k, wheelCentre(j, 'wheel_' + k)]));
77	  for (const s of ['l', 'r']) assert.ok(Math.abs(c['f' + s][0] - c['r' + s][0] - 2.075) < 0.15, `chiều dài cơ sở ${s}: ${c['f' + s][0] - c['r' + s][0]}`);
78	  assert.ok(c.fl[0] > 0 && c.rl[0] < 0, 'bánh trước phải ở +X (mũi xe)');
79	  assert.ok(Math.abs(c.fl[2] + c.fr[2]) < 0.02 && Math.abs(c.rl[2] + c.rr[2]) < 0.02, 'không đối xứng qua Z');
80	  assert.ok(c.fl[2] < 0 && c.fr[2] > 0, 'bánh trái (fl) phải ở -Z (trái khi mũi +X, Y lên)');
81	  assert.ok(c.fl[0] - c.rl[0] > 0 && Math.abs(c.fl[2] - c.fr[2]) > 1.2 && Math.abs(c.fl[2] - c.fr[2]) < 1.9, 'vết bánh ngoài khoảng');
82	  const bs = worldBoxes(j).filter(b => b.node.startsWith('wheel_'));
83	  for (const b of bs) assert.ok(b.tris > 0, `${b.node} rỗng`);
84	  /* bốn nút dùng chung một lưới; bánh phải xoay 180 độ quanh Y (nên bánh phải quay ngược góc, xem convert.py) */
85	  const w = Object.fromEntries(['fl', 'fr', 'rl', 'rr'].map(k => [k, nodeByName(j, 'wheel_' + k).n]));
86	  for (const k of ['fr', 'rl', 'rr']) assert.equal(w[k].mesh, w.fl.mesh, `wheel_${k} khác lưới với wheel_fl`);
87	  const rot = (n: any): number[] => n.rotation ?? [0, 0, 0, 1];
88	  for (const k of ['fl', 'rl']) assert.ok(rot(w[k]).slice(0, 3).every((x: number) => Math.abs(x) < 1e-3) && Math.abs(Math.abs(rot(w[k])[3]) - 1) < 1e-3, `wheel_${k} không được xoay`);
89	  for (const k of ['fr', 'rr']) { const q = rot(w[k]); assert.ok(Math.abs(q[0]) < 1e-3 && Math.abs(q[2]) < 1e-3 && Math.abs(Math.abs(q[1]) - 1) < 1e-3 && Math.abs(q[3]) < 1e-3, `wheel_${k} phải xoay 180 độ quanh Y: ${q}`); }
90	});
