// Kiểm tay Task 3: mở ?test&explore=bike trên dev server 5199, chụp xe ngày / đêm / phanh / xi nhan / cận cảnh
import { chromium } from 'file:///D:/2026%20-%20Tuan/danang-vite-xe-may/node_modules/playwright/index.mjs';
const OUT = 'D:/2026 - Tuan/danang-vite-xe-may/tests/screens/';
const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 960, height: 540 } });
page.setDefaultTimeout(300000);
const errors = [], warns = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|net::/.test(m.text())) errors.push(m.text()); if (m.type() === 'warning') warns.push(m.text()); });
await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
const t0 = Date.now();
await page.goto('http://localhost:5199/?test&explore=bike', { waitUntil: 'load', timeout: 300000 });
await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 300000, polling: 1000 });
await page.waitForFunction(() => window.__app.bike.state && window.__app.bike.model, null, { polling: 1000 });
console.log('trang xong', (Date.now() - t0) / 1000, 's');
await page.waitForFunction(() => window.__app.bike.model.real, null, { polling: 1000, timeout: 120000 }).catch(() => console.log('CHƯA real sau 120 s'));
console.log('real', await page.evaluate(() => window.__app.bike.model.real), (Date.now() - t0) / 1000, 's');
const wait = (ms) => page.waitForTimeout(ms);
const info = () => page.evaluate(() => { const b = window.__app.bike, m = b.model, a = m.anchors; const v = new window.__app.THREE.Vector3();
  const w = (o) => o.getWorldPosition(v).toArray().map((x) => +x.toFixed(3));
  return { s: { x: +b.state.x.toFixed(2), y: +b.state.y.toFixed(3), z: +b.state.z.toFixed(2), yaw: +b.state.yaw.toFixed(3), lean: +b.state.lean.toFixed(3), steer: +b.state.steer.toFixed(3), v: +b.state.v.toFixed(2) }, grip: w(a.gripL), seat: w(a.seat), eye: w(a.eye), calls: window.__app.renderer.info.render.calls }; });
await wait(3000);
console.log('ngay', JSON.stringify(await info()));
await page.screenshot({ path: OUT + 'bike-model.png' });
/* cận cảnh: tạm dừng camera lái (cam.mode khác 'bike'), đặt camera bên trái xe */
const close = async (name, dx, dy, dz) => {
  await page.evaluate(([dx, dy, dz]) => { const A = window.__app, s = A.bike.state; A.cam.mode = 'frozen';
    const c = Math.cos(s.yaw), sn = Math.sin(s.yaw);   // tiến (c, −sn), trái (−sn, −c)
    A.camera.position.set(s.x + dx * c - dz * sn, s.y + dy, s.z - dx * sn - dz * c); A.camera.lookAt(s.x, s.y + 0.7, s.z); }, [dx, dy, dz]);
  await wait(2500); await page.screenshot({ path: OUT + name });
  await page.evaluate(() => { window.__app.cam.mode = 'bike'; });
};
await close('bike-model-side.png', 0.3, 1.2, 3.2);
await close('bike-model-front.png', 3.0, 1.3, 1.2);
/* nghiêng + bẻ lái: chạy rồi rẽ trái */
await page.evaluate(() => { const b = window.__app.bike; for (let i = 0; i < 40; i++) b.step(0.1, { gas: 1, brake: 0, steer: 0, hard: false, grip: 1 }); for (let i = 0; i < 12; i++) b.step(0.1, { gas: 0.5, brake: 0, steer: 1, hard: false, grip: 1 }); });
await wait(2000);
console.log('re trai', JSON.stringify(await info()));
await page.screenshot({ path: OUT + 'bike-model-lean.png' });
await close('bike-model-lean-front.png', 3.0, 1.0, 0);
/* đêm: phanh + xi nhan trái */
await page.evaluate(() => { const A = window.__app; A.dayNight.target = 1; A.dayNight.night = 1; });
await wait(4000);
await page.evaluate(() => { const b = window.__app.bike; for (let i = 0; i < 10; i++) b.step(0.1, { gas: 0, brake: 1, steer: 0, hard: false, grip: 1 }); window.__app.bike.state.sig = 1; });
const lamp = () => page.evaluate(() => { const r = {}; window.__app.bike.model.group.traverse((o) => { if (o.isMesh) r[o.material.name] = o.material.userData.lampOn; }); return r; });
await wait(1500);
console.log('dem', JSON.stringify(await info()), 'braking', await page.evaluate(() => window.__app.bike.state.braking), 'den', JSON.stringify(await lamp()));
await page.screenshot({ path: OUT + 'bike-model-night.png' });
await close('bike-model-night-rear.png', -3.0, 1.0, 1.0);
await close('bike-model-night-front.png', 3.0, 1.0, -1.0);
console.log('loi', JSON.stringify(errors));
console.log('canh bao (bike)', JSON.stringify(warns.filter((w) => /xe máy|bike/i.test(w))));
await browser.close();

