const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 960, height: 540 } });
page.setDefaultTimeout(300000);
const errors = [], warns = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error' && !/fonts\.(googleapis|gstatic)|net::|Failed to load resource/.test(m.text())) errors.push(m.text()); if (m.type() === 'warning') warns.push(m.text()); });
await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.abort());
await page.route(/bike\/scooter\.glb/, (r) => r.abort());
await page.goto('http://localhost:5199/?test&explore=bike', { waitUntil: 'load', timeout: 300000 });
await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done') && window.__app.bike.model, null, { timeout: 300000, polling: 1000 });
await page.waitForTimeout(4000);
console.log('real', await page.evaluate(() => window.__app.bike.model.real));
await page.screenshot({ path: 'D:/2026 - Tuan/danang-vite-xe-may/tests/screens/bike-model-blocked.png' });
console.log('loi', JSON.stringify(errors)); console.log('canh bao', JSON.stringify(warns.filter((w) => /xe máy/i.test(w))));
await browser.close();
EOF
